package vn.boardinghub.modules.audit;import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="audit_logs")public class AuditLog{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=160)private String actor;@Column(nullable=false,length=80)private String action;@Column(nullable=false,length=80)private String entityType;@Column(length=80)private String entityId;@Column(length=1000)private String detail;@Column(nullable=false)private Instant occurredAt=Instant.now();protected AuditLog(){}public AuditLog(String actor,String action,String entityType,String entityId,String detail){this.actor=actor;this.action=action;this.entityType=entityType;this.entityId=entityId;this.detail=detail;}}
